<script setup lang="ts">
import MoneyInput from './MoneyInput.vue';
import { computed, reactive, ref, watch } from 'vue';
import { state, mutate, mutation, today } from '../store.ts';
import { id, money, normalize, localDay, duplicateCandidates, type Bill, type Review, type Transaction } from '../domain.ts';
import { fromZonedTime } from '../timezone.ts';
import { calculateReceipt, splitItems, type ItemSplit } from '../item-split.ts';
import SplitForm from './SplitForm.vue';
import ReceiptScanReview from './ReceiptScanReview.vue';
import { normalizeReceipt, type ReceiptData } from '../receipt.ts';
const props = defineProps<{ existing?: Bill; review?: Review; transaction?: Transaction }>();
const emit = defineEmits<{ saved: []; dirty: [value: boolean] }>();
const manual = ref(!!props.existing && !props.existing.itemSplit?.settings);
const locked = computed(() => !!props.existing && [...props.existing.settlements, ...props.existing.resolutions].some(event => !event.reversed));
const people = ref(props.existing?.members.map(person => ({ id: person.id, name: person.displayName, self: person.isSelf })) ?? [{ id: id(), name: 'Saya', self: true }, { id: id(), name: 'Teman', self: false }]);
const draft = reactive<ItemSplit>(JSON.parse(JSON.stringify(props.existing?.itemSplit ?? { items: [{ id: id(), name: '', quantity: 1, unitPrice: '', allocations: [] }], tax: '0', service: '0', discount: '0', settings: { serviceRate: 5, taxRate: 10, taxOnService: false } })));
const form = reactive({ title: props.existing?.title ?? props.transaction?.merchant ?? props.review?.merchant.value ?? '', payer: props.existing?.payer.other?.memberID ?? 'self', account: props.existing?.payer.selfPaid?.accountID ?? props.transaction?.accountID ?? state.data.accounts.find(row => !row.archived)?.id ?? '', category: props.existing?.categoryID ?? props.transaction?.categoryID ?? state.data.categories.find(row => row.kind === 'expense' && !row.archived)?.id ?? '', date: props.existing ? localDay(props.existing.occurredAt, state.timezone) : props.review?.date.value ?? today(), note: props.existing?.note ?? '' });
const newName = ref('');
const assignmentMode = ref('menu');
const activePerson = ref(people.value[0]?.id ?? '');
const error = ref('');
const copied = ref(false);
const receiptTotal = ref<string>();
const mismatchConfirmed = ref(false);
const duplicateConfirmed = ref(false);
const result = computed(() => { try { return calculateReceipt(draft, people.value.map(person => person.id)); } catch { return null; } });
const candidates = computed(() => props.review ? duplicateCandidates(state.data, { ...props.review, amount: { ...props.review.amount, value: result.value?.total ?? '0' }, merchant: { ...props.review.merchant, value: form.title }, date: { ...props.review.date, value: form.date } }, form.payer === 'self' ? form.account : '') : []);
const totals = computed(() => (['subtotal', 'discount', 'service', 'tax', 'rounding', 'total'] as const).map(key => result.value?.rows.reduce((sum, row) => sum + BigInt(row[key]), 0n).toString() ?? '0'));
const receiptDifference = computed(() => receiptTotal.value && result.value ? BigInt(result.value.total) - BigInt(receiptTotal.value) : 0n);
function applyReceipt(data: ReceiptData) {
  draft.items = data.items.map(item => ({ id: id(), name: item.name, quantity: item.qty, unitPrice: String(item.unit_price ?? 0), allocations: [] }));
  const base = data.subtotal ?? data.items.reduce((sum, item) => sum + item.qty * (item.unit_price ?? 0), 0);
  draft.settings = { serviceRate: base ? Math.round((data.service_charge ?? 0) / base * 10000) / 100 : 0, taxRate: base ? Math.round((data.tax ?? 0) / base * 10000) / 100 : 0, taxOnService: false, taxIncluded: data.tax_included_in_price };
  draft.discount = String(data.discount); draft.rounding = String(data.rounding);
  if (data.merchant) form.title = data.merchant;
  if (data.date) form.date = data.date;
  receiptTotal.value = data.grand_total === null ? undefined : String(data.grand_total);
  mismatchConfirmed.value = false;
}
if (props.review?.receipt) applyReceipt(normalizeReceipt(props.review.receipt));
watch([draft, people, form], () => { emit('dirty', true); copied.value = false; mismatchConfirmed.value = false; }, { deep: true });
watch(draft, () => { for (const item of draft.items) { if ((item.quantity as unknown) === '') item.quantity = 0; } if (draft.settings) { if ((draft.settings.serviceRate as unknown) === '') draft.settings.serviceRate = 0; if ((draft.settings.taxRate as unknown) === '') draft.settings.taxRate = 0; } }, { deep: true });
function addPerson() { const name = newName.value.trim(); if (!name || people.value.length >= 20) return; if (people.value.some(person => normalize(person.name) === normalize(name))) { error.value = 'Nama peserta tidak boleh sama.'; return; } people.value.push({ id: id(), name, self: false }); newName.value = ''; error.value = ''; }
function removePerson(personID: string) { people.value = people.value.filter(person => person.id !== personID); for (const item of draft.items) item.allocations = item.allocations.filter(entry => entry.memberID !== personID); if (form.payer === personID) form.payer = 'self'; if (activePerson.value === personID) activePerson.value = people.value[0]?.id ?? ''; }
function toggleOwner(itemID: string, memberID: string, checked: boolean) { const item = draft.items.find(row => row.id === itemID)!; item.allocations = item.allocations.filter(entry => entry.memberID !== memberID); if (checked) item.allocations.push({ memberID, quantity: 1 }); }
async function copySummary() { try { await navigator.clipboard.writeText([`Split Bill - ${form.title || 'Tagihan bersama'} (${form.date})`, ...people.value.map(person => `${person.name}: ${money(result.value?.shares[person.id] ?? '0')}`), `Total: ${money(result.value?.total ?? '0')}`].join('\n')); copied.value = true; } catch { error.value = 'Ringkasan belum tersalin. Izinkan akses clipboard lalu coba lagi.'; } }
async function save() {
  error.value = '';
  if (locked.value) { error.value = 'Tagihan dikunci setelah pelunasan.'; return; }
  if (receiptDifference.value !== 0n && !mismatchConfirmed.value) { error.value = 'Total pembagian belum sama dengan struk. Sesuaikan biaya atau konfirmasi koreksi.'; return; }
  if (candidates.value.length && !duplicateConfirmed.value) { error.value = 'Periksa transaksi mirip sebelum menyimpan.'; return; }
  try { splitItems(draft, people.value.map(person => person.id)); } catch { error.value = 'Isi nama menu, harga, peserta dan pemesan setiap menu.'; return; }
  if (new Set(people.value.map(person => normalize(person.name))).size !== people.value.length) { error.value = 'Nama peserta tidak boleh sama.'; return; }
  const payload: Record<string, unknown> = { ...mutation(), p_title: form.title, p_total: result.value!.total, p_item_split: structuredClone(JSON.parse(JSON.stringify(draft))), p_payer_kind: form.payer === 'self' ? 'self' : 'other', p_payer_member_id: form.payer === 'self' ? null : form.payer, p_payer_account_id: form.payer === 'self' ? form.account : null, p_category_id: form.category, p_occurred_at: props.existing && localDay(props.existing.occurredAt, state.timezone) === form.date ? props.existing.occurredAt : fromZonedTime(form.date, state.timezone), p_note: form.note || null, p_members: people.value.map((person, index) => ({ id: person.id, display_name: person.name, is_self: person.self, sort_order: index, share_amount: result.value!.shares[person.id] })) };
  if (props.existing) { payload.p_split_bill_id = props.existing.id; payload.p_expected_version = props.existing.version; }
  if (props.review) { payload.p_review_item_id = props.review.id; payload.p_client_mutation_id = props.review.id; }
  if (props.transaction) { payload.p_transaction_id = props.transaction.id; payload.p_expected_version = props.transaction.version; }
  if (await mutate('save_item_split_bill', payload, 'Tagihan bersama tersimpan')) { emit('dirty', false); emit('saved'); }
}
</script>
<template>
  <div v-if="!existing" class="segmented receipt-mode" aria-label="Cara pembagian"><button type="button" :class="{ active: !manual }" @click="manual = false">Sesuai pesanan</button><button type="button" :class="{ active: manual }" @click="manual = true">Bagi total</button></div>
  <SplitForm v-if="manual" v-bind="props" @saved="emit('saved')" @dirty="emit('dirty', $event)" />
  <form v-else class="receipt-split" @submit.prevent="save">
    <ReceiptScanReview v-if="!locked" @apply="applyReceipt" @dirty="emit('dirty', true)" />
    <section class="receipt-card"><h3><span>01</span> Siapa saja yang ikut?</h3><fieldset :disabled="locked"><div class="receipt-chips"><span v-for="person in people" :key="person.id" class="receipt-chip">{{ person.name }}<button v-if="!person.self" type="button" :aria-label="`Hapus peserta ${person.name}`" @click="removePerson(person.id)">×</button></span></div><div class="receipt-person-add"><label>Nama orang<input v-model="newName" maxlength="80" placeholder="Misalnya, Ani" @keydown.enter.prevent="addPerson"></label><button type="button" class="primary" :disabled="people.length >= 20 || !newName.trim()" @click="addPerson">Tambah orang</button></div></fieldset></section>
    <section class="receipt-card"><h3><span>02</span> Menu yang dipesan</h3><p class="receipt-hint">Menu bersama dibagi rata.</p><fieldset :disabled="locked"><div class="segmented receipt-mode" aria-label="Cara memilih pemesan"><button type="button" :class="{ active: assignmentMode === 'menu' }" @click="assignmentMode = 'menu'">Per menu</button><button type="button" :class="{ active: assignmentMode === 'person' }" @click="assignmentMode = 'person'">Per orang</button></div><label v-if="assignmentMode === 'person'">Pilih pemesan<select v-model="activePerson"><option v-for="person in people" :key="person.id" :value="person.id">{{ person.name }}</option></select></label><div v-for="(item, index) in draft.items" :key="item.id" class="receipt-item"><div class="receipt-item-inputs"><label>Nama menu<input v-model="item.name" maxlength="160" :aria-label="`Nama menu ${index + 1}`" placeholder="Ayam bakar combo"></label><label>Harga satuan (Rp)<MoneyInput v-model="item.unitPrice" :aria-label="`Harga menu ${index + 1}`" placeholder="35.000" /></label><label>Qty<input v-model.number="item.quantity" type="number" min="0" max="999999" :aria-label="`Jumlah menu ${index + 1}`"></label><button type="button" class="secondary" :aria-label="`Hapus menu ${item.name || index + 1}`" @click="draft.items.splice(index, 1)">Hapus</button></div><div class="receipt-owners"><label v-for="person in people.filter(row => assignmentMode === 'menu' || row.id === activePerson)" :key="person.id" class="receipt-owner"><input type="checkbox" :checked="item.allocations.some(entry => entry.memberID === person.id)" @change="toggleOwner(item.id, person.id, ($event.target as HTMLInputElement).checked)">{{ person.name }}</label></div></div><button type="button" class="primary" :disabled="draft.items.length >= 100" @click="draft.items.push({ id: id(), name: '', unitPrice: '', quantity: 1, allocations: [] })">Tambah menu</button></fieldset></section>
    <section class="receipt-card"><h3><span>03</span> Biaya tambahan</h3><fieldset :disabled="locked"><div class="receipt-rates"><label>Service (%)<input v-model.number="draft.settings!.serviceRate" type="number" min="0" max="100" step="0.01" :disabled="draft.settings!.taxIncluded"></label><label>Pajak / PB1 (%)<input v-model.number="draft.settings!.taxRate" type="number" min="0" max="100" step="0.01" :disabled="draft.settings!.taxIncluded"></label><label>Diskon (Rp)<MoneyInput v-model="draft.discount" /></label><label>Pembulatan struk (Rp)<MoneyInput v-model="draft.rounding" placeholder="0" signed /></label></div><label class="receipt-owner"><input v-model="draft.settings!.taxIncluded" type="checkbox">Harga sudah termasuk pajak dan service</label><label class="receipt-owner"><input v-model="draft.settings!.taxOnService" type="checkbox" :disabled="draft.settings!.taxIncluded">Hitung pajak dari subtotal + service</label></fieldset></section>
    <section class="receipt-card receipt-result"><div class="receipt-result-heading"><h3>Hasil pembagian</h3><span>Otomatis diperbarui</span></div><p v-if="result?.unassigned.length" class="error-text" role="alert">Belum ada pemesan: {{ result.unassigned.join(', ') }}.</p><p v-if="!result" class="error-text" role="alert">Periksa harga, qty, diskon, pembulatan dan tarif 0–100% (maksimal dua desimal).</p><div v-if="result" class="receipt-table-scroll"><table><caption class="sr-only">Pembagian tagihan per orang dalam Rupiah</caption><thead><tr><th scope="col">Nama</th><th scope="col">Pesanan</th><th scope="col">Diskon</th><th scope="col">Service</th><th scope="col">Pajak</th><th scope="col">Pembulatan</th><th scope="col">Bayar</th></tr></thead><tbody><tr v-for="row in result.rows" :key="row.id"><th scope="row">{{ people.find(person => person.id === row.id)?.name }}</th><td>{{ money(row.subtotal) }}</td><td>{{ money(row.discount) }}</td><td>{{ money(row.service) }}</td><td>{{ money(row.tax) }}</td><td>{{ money(row.rounding) }}</td><td>{{ money(row.total) }}</td></tr></tbody><tfoot><tr><th scope="row">Total</th><td v-for="(amount, index) in totals" :key="index">{{ money(amount) }}</td></tr></tfoot></table></div><div v-if="receiptTotal && result && !result.unassigned.length" role="status"><p :class="receiptDifference ? 'error-text' : 'receipt-hint'">{{ receiptDifference ? `Selisih terhadap struk: ${money(receiptDifference)}. Periksa diskon dan tarif.` : 'Total pembagian sama persis dengan total struk.' }}</p><template v-if="receiptDifference"><button type="button" class="secondary" :disabled="locked" @click="draft.rounding = (BigInt(draft.rounding || '0') - receiptDifference).toString()">Sesuaikan pembulatan dengan struk</button><label class="receipt-owner"><input v-model="mismatchConfirmed" type="checkbox">Saya sudah memeriksa; gunakan total hasil koreksi.</label></template></div><button type="button" class="secondary" :disabled="!result || !!result.unassigned.length" @click="copySummary">{{ copied ? 'Ringkasan tersalin' : 'Salin ringkasan' }}</button><span class="sr-only" role="status">{{ copied ? 'Ringkasan berhasil disalin' : '' }}</span></section>
    <details class="receipt-card" open><summary>Pencatatan tagihan</summary><div class="entry-form"><label>Nama tagihan<input v-model="form.title" required maxlength="160" placeholder="Restoran ABC"></label><div class="form-grid"><label>Pembayar<select v-model="form.payer"><option value="self">Saya</option><option v-for="person in people.filter(row => !row.self)" :key="person.id" :value="person.id">{{ person.name }}</option></select></label><label v-if="form.payer === 'self'">Akun pembayaran<select v-model="form.account" required><option v-for="account in state.data.accounts.filter(row => !row.archived)" :key="account.id" :value="account.id">{{ account.name }}</option></select></label><label>Kategori<select v-model="form.category" required><option v-for="category in state.data.categories.filter(row => !row.archived && row.kind === 'expense')" :key="category.id" :value="category.id">{{ category.name }}</option></select></label><label>Tanggal<input v-model="form.date" type="date" required></label></div><label>Catatan (opsional)<textarea v-model="form.note" maxlength="2000" rows="2"></textarea></label></div></details>
    <div v-if="candidates.length" class="callout sun"><strong>Periksa transaksi mirip.</strong><p v-for="candidate in candidates" :key="candidate.id">{{ candidate.merchant }} · {{ money(candidate.amount) }}</p><label class="checkbox"><input v-model="duplicateConfirmed" type="checkbox">Saya sudah memeriksa; ini tagihan berbeda.</label></div>
    <p v-if="locked" class="receipt-hint">Tagihan dikunci setelah pelunasan. Ringkasan tetap dapat disalin.</p><p v-if="error || state.error" role="alert" class="error-text">{{ error || state.error }}</p><button class="primary full" :disabled="locked || state.saving || !result || result.total === '0' || !!result.unassigned.length || people.length < 2 || (!state.online && state.mode !== 'demo')">{{ state.saving ? 'Menyimpan…' : 'Simpan tagihan' }}</button>
  </form>
</template>
<style scoped>
.receipt-split{--receipt-bg:var(--canvas);--receipt-card:var(--surface);--receipt-ink:var(--ink);--receipt-mute:var(--muted);--receipt-line:var(--border);--receipt-acc:var(--primary);--receipt-chip:var(--primary-soft);display:grid;gap:16px;max-width:760px;margin:auto;padding:20px;background:var(--receipt-bg);color:var(--receipt-ink);border-radius:20px;font-family:'Segoe UI',system-ui,sans-serif;font-size:16px}.receipt-intro h3{font-size:26px;margin:8px 0}.receipt-intro p,.receipt-hint{color:var(--receipt-mute);line-height:1.6}.receipt-eyebrow{font-size:12px;letter-spacing:.12em;color:var(--receipt-acc);font-weight:700}.receipt-card{background:var(--receipt-card);border:1px solid var(--receipt-line);border-radius:16px;padding:20px;min-width:0}.receipt-card h3{display:flex;gap:10px;align-items:center;font-size:17px;margin:0 0 16px}.receipt-card h3>span{font-size:12px;color:var(--receipt-acc);font-variant-numeric:tabular-nums}.receipt-split fieldset{border:0;padding:0;margin:0;min-width:0}.receipt-chips,.receipt-owners{display:flex;flex-wrap:wrap;gap:8px}.receipt-chip{display:inline-flex;align-items:center;gap:6px;padding:4px 8px 4px 14px;border-radius:999px;background:var(--receipt-chip);overflow-wrap:anywhere;max-width:100%}.receipt-chip button{background:none;color:inherit;width:44px;min-height:44px;font-size:22px}.receipt-person-add{display:flex;gap:12px;align-items:end;margin-top:16px}.receipt-person-add label{flex:1;min-width:0}.receipt-item{padding:0 0 20px;margin:0 0 20px;border-bottom:1px dashed var(--receipt-line)}.receipt-item-inputs{display:grid;grid-template-columns:minmax(0,2fr) minmax(0,1.3fr) minmax(64px,.6fr) auto;gap:10px;align-items:end}.receipt-split label{font-size:14px;gap:6px;color:var(--receipt-mute)}.receipt-split input,.receipt-split select,.receipt-split textarea{background:var(--receipt-card);color:var(--receipt-ink);border-color:var(--receipt-line);font:inherit;width:100%;min-width:0}.receipt-owners{margin-top:12px}.receipt-owner{display:flex!important;flex-direction:row!important;align-items:center;gap:8px!important;min-height:44px;padding:4px 10px;cursor:pointer;color:var(--receipt-ink)!important}.receipt-owner:has(input:checked){background:var(--receipt-chip);border-radius:10px}.receipt-owner input{width:18px;height:18px;accent-color:var(--receipt-acc)}.receipt-rates{display:grid;grid-template-columns:1fr 1fr;gap:16px;margin-bottom:12px}.receipt-split .primary{background:var(--receipt-acc);color:#fff}.receipt-split .secondary{background:transparent;color:var(--receipt-ink);border-color:var(--receipt-line)}.receipt-hint{font-size:13px;margin:12px 0}.receipt-result-heading{display:flex;flex-wrap:wrap;align-items:baseline;justify-content:space-between;gap:8px}.receipt-result-heading>span{font-size:12px;color:var(--receipt-mute)}.receipt-table-scroll{overflow-x:auto}.receipt-split table{border-collapse:collapse;width:100%;font-size:13px;font-variant-numeric:tabular-nums}.receipt-split th,.receipt-split td{padding:12px 8px;border-bottom:1px solid var(--receipt-line);text-align:right;white-space:nowrap}.receipt-split th:first-child{text-align:left;white-space:normal;overflow-wrap:anywhere;min-width:64px}.receipt-split thead th{color:var(--receipt-mute);font-weight:500}.receipt-split td:last-child{color:var(--receipt-acc);font-weight:700}.receipt-split tfoot{font-weight:700}.receipt-split summary{font-weight:600;cursor:pointer;margin-bottom:16px}.receipt-mode{margin-bottom:16px}.receipt-split :focus-visible{outline:2px solid var(--receipt-acc);outline-offset:3px}
:global([data-theme='dark'] .receipt-split){--receipt-bg:var(--canvas);--receipt-card:var(--surface);--receipt-ink:var(--ink);--receipt-mute:var(--muted);--receipt-line:var(--border);--receipt-acc:var(--primary);--receipt-chip:var(--primary-soft)}:global([data-theme='dark'] .receipt-split .primary){color:var(--on-primary)}:global([data-theme='dark'] .receipt-split .error-text){color:var(--expense)}
@media(max-width:600px){.receipt-split{padding:12px;gap:12px}.receipt-card{padding:16px}.receipt-item-inputs{grid-template-columns:minmax(0,1fr) 80px}.receipt-item-inputs>label:first-child{grid-column:1/-1}.receipt-person-add{flex-direction:column;align-items:stretch}.receipt-table-scroll{margin:0 -8px}.receipt-split th,.receipt-split td{padding:10px 6px}}
</style>
